<template>
<el-dialog v-model="visible" title="本批次还料确认" width="min(1400px,96vw)" top="4vh" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" :before-close="close" class="batch-return-dialog">
 <p v-if="loading" role="status">正在加载批次资料…</p>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error&&!busy" @click="refresh">刷新资料</el-button>
 <template v-if="info">
 <p>{{info.orderNo}} / {{info.processName}} / {{info.batchNo}}</p>
 <p>本批产出：{{info.completedQuantity}}件 / {{info.outputWeight}}g；领料：{{info.weights.issued}}g；已还：{{info.weights.returned}}g</p>
 <el-alert v-if="info.phase==='AWAITING_OUTPUT'" title="请先完成本批次一次产出入库，再确认全部还料或无余料。" type="info" :closable="false"/>
 <template v-else-if="info.phase==='AWAITING_RETURN'">
 <el-form ref="returnForm" :model="formModel" :rules="formRules" scroll-to-error label-width="100px" :disabled="busy||loading||needsReload">
  <el-form-item label="还料方式"><el-radio-group v-model="mode"><el-radio value="RETURNED">有余料，一次提交全部还料</el-radio><el-radio value="NONE">无余料</el-radio></el-radio-group></el-form-item>
  <template v-if="mode==='RETURNED'">
   <el-form-item label="还库日期" prop="date"><el-date-picker v-model="date" type="date" value-format="YYYY-MM-DD"/></el-form-item>
   <el-form-item label="经办人" prop="operators"><el-select fit-input-width popper-class="batch-return-source-options" v-model="operators" multiple filterable><el-option v-for="p in people" :key="p.id" :label="personLabel(p)" :value="p.id"/></el-select></el-form-item>
   <el-form-item label="仓管员" prop="keeper"><el-select fit-input-width popper-class="batch-return-source-options" v-model="keeper" filterable><el-option v-for="p in people" :key="p.id" :label="personLabel(p)" :value="p.id"/></el-select></el-form-item>
   <div class="return-tools"><el-button @click="add">添加还料</el-button><el-select fit-input-width popper-class="batch-return-source-options" v-model="importType" aria-label="导入还料类型"><el-option v-for="t in returnTypes" :key="t" :value="t" :label="orderTypeNames[t]"/></el-select><el-select fit-input-width popper-class="batch-return-source-options" v-model="importWarehouse" aria-label="导入仓库" placeholder="导入仓库"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select><el-button v-if="actionPermission.has('metal:warehouse-order:import')" @click="downloadTemplate">模板下载</el-button><el-button v-if="actionPermission.has('metal:warehouse-order:import')" @click="file?.click()">导入预览</el-button><input ref="file" type="file" accept=".xlsx" hidden @change="importFile"/></div>
   <el-table :data="lines" border class="return-lines">
    <el-table-column label="还料类型" min-width="170"><template #default="{row,$index}"><el-select fit-input-width popper-class="batch-return-source-options" v-model="row.type" @change="resetLine(row)"><el-option v-for="t in returnTypes" :key="t" :value="t" :label="orderTypeNames[t]"/></el-select></template></el-table-column>
    <el-table-column label="原出库明细／回收原材料" min-width="300"><template #default="{row,$index}"><el-select fit-input-width popper-class="batch-return-source-options" v-model="row.choice" filterable @change="choose(row)" placeholder="请选择物料来源"><el-option v-for="o in choices(row)" :key="o.id" :value="o.id" :label="choiceLabel(o,row.type)"/></el-select></template></el-table-column>
    <el-table-column label="还库仓库" min-width="180"><template #default="{row,$index}"><el-select fit-input-width popper-class="batch-return-source-options" v-model="row.warehouseId" :disabled="row.type!=='PROCESS_RAW_RETURN'"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></template></el-table-column>
    <el-table-column label="实测净重(g)" min-width="150"><template #default="{row,$index}"><el-form-item :prop="`lines.${$index}.netWeight`" :rules="[fieldRule(v=>decimalError(v,'还库净重',{positive:row.type!=='RAW_RETURN'}))]" label-width="0"><el-input v-model="row.netWeight" inputmode="decimal" aria-label="还库净重"/></el-form-item></template></el-table-column>
    <el-table-column label="半成品件数" min-width="120"><template #default="{row,$index}"><el-form-item v-if="row.type==='SEMI_RETURN'" :prop="`lines.${$index}.quantity`" :rules="[fieldRule(v=>integerError(quantityInputs.get(row)??v,'还库件数'))]" label-width="0"><el-input v-model="row.quantity" @input="v=>quantityInputs.set(row,String(v))" inputmode="numeric" aria-label="还库件数"/></el-form-item><span v-else>—</span></template></el-table-column>
    <el-table-column label="毛重(g)／杂质(g)（选填）" min-width="190"><template #default="{row,$index}"><el-form-item :prop="`lines.${$index}.grossWeight`" :rules="[fieldRule(v=>decimalError(v,'毛重',{optional:true}))]" label-width="0"><el-input v-model="row.grossWeight" placeholder="毛重"/></el-form-item><el-form-item :prop="`lines.${$index}.impurity`" :rules="[fieldRule(v=>decimalError(v,'杂质',{optional:true}))]" label-width="0"><el-input v-model="row.impurity" placeholder="杂质"/></el-form-item></template></el-table-column>
    <el-table-column label="操作" width="80"><template #default="{$index}"><el-button type="danger" link @click="lines.splice($index,1)">删除</el-button></template></el-table-column>
   </el-table>
   <p>本单还料合计：{{pendingWeight}}g；预计本批损耗：{{estimatedLoss}}g。按实测填写，不能用可退上限替代实物称重。</p>
  </template>
  <p v-else>确认现场没有需要还库的原材料、未加工半成品或可回收粉末边角料。重量差额仍按规则计入损耗。</p>
  <el-form-item label="核对说明" prop="reason" :required="mode==='RETURNED'"><el-input v-model="reason" type="textarea" maxlength="500" :placeholder="mode==='NONE'?'无余料核对说明（选填）':'填写本次全部还料的原因'"/></el-form-item>
  <el-form-item prop="checked" label-width="0"><el-checkbox v-model="checked">已核对全部实物；{{mode==='NONE'?'确认无余料':'全部需还物料均已填入本次清单'}}</el-checkbox></el-form-item>
 </el-form>
 <p v-if="!canSettle">没有批次结算权限，请由有权限人员完成最后确认。</p>
 </template>
 <template v-else><el-alert title="本批次已结束，不能追加还料。" type="success" :closable="false"/><p v-for="r in info.reports" :key="r.completedQuantity">完成{{r.completedQuantity}}件；损耗{{r.lossWeight}}g</p><p v-if="info.processRemainingQuantity">本工序尚余{{info.processRemainingQuantity}}件，可另建批次继续加工。</p><p v-else>本工序已足额完成，无需再建批次。</p><p v-for="d in info.documents" :key="d.id">{{orderTypeNames[d.type]}}：{{d.orderNo}}</p><p>下一工序请按生产领料规则选择已结算半成品；不会自动扣料。</p><el-button v-if="info.status==='SETTLED'&&info.nextProcess&&canSettle" type="primary" @click="nextStep">去下一工序领料：{{info.nextProcess.processName}}</el-button></template>
 </template>
 <template #footer><el-button :disabled="busy" @click="close()">关闭</el-button><el-button v-if="info?.phase==='AWAITING_RETURN'&&canSettle" type="primary" :loading="busy" :disabled="loading||!!error||needsReload||!canSettle" @click="submit">{{mode==='NONE'?'确认无余料并结算':'确认全部还料并结算'}}</el-button></template>
</el-dialog>
</template>
<script setup lang="ts">
import type {FormInstance} from 'element-plus'
import {fieldRule,textRules,decimalError,integerError,applyFieldErrors,remapFieldErrors,returnFieldPath} from '@/utils/input-validation'
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission = useActionPermission()
import {ref,computed,onBeforeUnmount,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessage} from 'element-plus'
import useUserStore from '@/store/modules/user'
import {batchCompletionContext,confirmBatchReturn,warehouseOptions,importWarehouseLines,orderTypeNames,type Row} from '@/api/metal/warehouse'
import {personLabel} from '@/utils/person-label'
import {createUUID} from '@/utils/uuid'
import request from '@/utils/request'
const emit=defineEmits(['saved','busy-change','next-step']),visible=ref(false),loading=ref(false),busy=ref(false),error=ref(''),needsReload=ref(false),info=ref<Row>(),lines=ref<Row[]>([]),people=ref<Row[]>([]),materials=ref<Row[]>([]),warehouses=ref<Row[]>([]),mode=ref('RETURNED'),checked=ref(false),reason=ref(''),operators=ref<string[]>([]),keeper=ref(''),date=ref(''),file=ref<HTMLInputElement>(),importType=ref('RAW_RETURN'),importWarehouse=ref('');
const returnTypes=['RAW_RETURN','SEMI_RETURN','PROCESS_RAW_RETURN'],user=useUserStore(),canSettle=computed(()=>actionPermission.hasAll(['metal:process-batch:settle','metal:warehouse-order:add']));
let epoch=0,target='',requestId='',disposed=false;
watch(busy,v=>emit('busy-change',v));
function units(x:unknown){const s=String(x??'');if(!/^\d{1,14}(\.\d{1,6})?$/.test(s))throw Error('重量须为非负数字，最多6位小数');const[a,b='']=s.split('.');return BigInt(a)*1000000n+BigInt(b.padEnd(6,'0'))}
function weight(x:bigint){const sign=x<0n?'-':'';if(x<0n)x=-x;return sign+(x/1000000n)+'.'+String(x%1000000n).padStart(6,'0')}
const pendingWeight=computed(()=>{try{return weight(lines.value.reduce((n,r)=>n+units(r.netWeight),0n))}catch{return '—'}}),estimatedLoss=computed(()=>{try{return weight(units(info.value?.weights.issued)-units(info.value?.weights.returned)-units(info.value?.outputWeight)-(mode.value==='NONE'?0n:units(pendingWeight.value)))}catch{return '—'}});
function close(done?:()=>void){if(busy.value)return;epoch++;visible.value=false;loading.value=false;info.value=undefined;error.value='';done?.()}
watch(visible,v=>{if(!v){epoch++;loading.value=false}});
function current(ticket:number,id:string){return !disposed&&visible.value&&epoch===ticket&&target===id}
async function open(id:string){if(busy.value)return;close();target=String(id);requestId=createUUID();lines.value=[];operators.value=[];keeper.value='';mode.value='RETURNED';checked.value=false;reason.value='';date.value=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());needsReload.value=false;visible.value=true;await refresh()}
async function refresh(){if(busy.value||!target)return;const ticket=++epoch,id=target,valid=()=>current(ticket,id);loading.value=true;error.value='';info.value=undefined;try{const data=(await batchCompletionContext(id,valid)).data;if(!valid())return;const opts=await Promise.all(['people','materials','warehouses'].map(k=>warehouseOptions(k,data.factoryId,undefined,valid)));if(!valid())return;info.value=data;[people.value,materials.value,warehouses.value]=opts.map(o=>o.data);needsReload.value=false}catch(e:any){if(valid())error.value=e?.message||'批次资料加载失败，请重试'}finally{if(valid())loading.value=false}}
function add(){lines.value.push({type:'RAW_RETURN',choice:'',warehouseId:'',quantity:0,netWeight:'',grossWeight:'',impurity:''})}
function nextStep(){if(busy.value||!info.value?.nextProcess)return;const next={factoryId:info.value.factoryId,workOrderId:info.value.workOrderId,itemId:info.value.itemId,processId:info.value.nextProcess.processId};close();emit('next-step',next)}
function resetLine(row:Row){quantityInputs.delete(row);returnForm.value?.clearValidate();Object.assign(row,{choice:'',sourceLineId:null,referenceId:null,warehouseId:'',quantity:0,netWeight:'',grossWeight:'',impurity:''})}
function choices(row:Row){return row.type==='PROCESS_RAW_RETURN'?materials.value:(info.value?.sources??[]).filter((s:Row)=>s.category===(row.type==='SEMI_RETURN'?'SEMI':'RAW'))}
function choiceLabel(o:Row,type:string){
 if(type==='PROCESS_RAW_RETURN')return `${o.code} / ${o.name} / ${o.specification||'未填写规格'}`;
 const prefix=String(o.orderNo??'')+' / ',name=String(o.name??''),display=name.startsWith(prefix)?name.slice(prefix.length):name;
 const origin=type==='SEMI_RETURN'?` / ${o.specification||'规格未记录'} / 已完成：${o.originProcessSequence?'第'+o.originProcessSequence+'道·':''}${o.originProcessName||'来源工序未记录'} / 来源工单：${o.originWorkOrderNo||'未记录'} / 批次：${o.batchNo||'未记录'}`:'';
 return `${o.orderNo} / ${o.code} / ${display}${origin} / 可还${o.returnableWeight}g${type==='SEMI_RETURN'?' / '+o.remainingQuantity+'件':''}`;
}
function choose(row:Row){const source=choices(row).find((o:Row)=>o.id===row.choice);if(row.type==='PROCESS_RAW_RETURN'){row.referenceId=source?.id;row.sourceLineId=null;row.quantity=0}else{row.sourceLineId=source?.id;row.referenceId=source?.referenceId;row.warehouseId=source?.warehouseId;if(row.type!=='SEMI_RETURN')row.quantity=0}}
function validateRows(rows:Row[]){if(rows.length>1000)throw Error('本次最多1000条明细');let sum=0n,semiPieces=0;let semiLimit=Infinity;const sourceWeights=new Map<string,bigint>(),sourcePieces=new Map<string,number>();for(const r of rows){if(!r.warehouseId||!r.choice)throw Error('请选择全部物料来源及仓库');const net=units(r.netWeight);if(net===0n&&r.type!=='RAW_RETURN')throw Error('半成品和加工余料须填写正数实测还库净重');sum+=net;if(r.type==='SEMI_RETURN'&&(!Number.isInteger(r.quantity)||r.quantity<1))throw Error('半成品还库件数须为正整数');if(r.grossWeight!==''&&r.grossWeight!=null||r.impurity!==''&&r.impurity!=null){if(units(r.grossWeight)-units(r.impurity)!==net)throw Error('毛重、杂质须成对填写，净重等于毛重减杂质')}if(r.type!=='PROCESS_RAW_RETURN'){const source=(info.value?.sources??[]).find((o:Row)=>o.id===r.sourceLineId&&o.category===(r.type==='SEMI_RETURN'?'SEMI':'RAW'));if(!source||String(source.warehouseId)!==String(r.warehouseId))throw Error('原出库来源失效，请刷新');const key=String(source.id),w=(sourceWeights.get(key)??0n)+net;sourceWeights.set(key,w);if(w>units(source.remainingWeight))throw Error('累计还库净重超过原出库剩余量');if(r.type==='SEMI_RETURN'){semiPieces+=r.quantity;semiLimit=Math.min(semiLimit,Number(source.batchReturnableQuantity));const q=(sourcePieces.get(key)??0)+r.quantity;sourcePieces.set(key,q);if(q>Number(source.remainingQuantity))throw Error('累计还库件数超过原出库剩余件数')}}}if(sum===0n)throw Error('没有实际还料，请选择无余料确认');if(semiPieces>semiLimit)throw Error('半成品还库件数超过本批扣除产出后的可还件数');if(sum>units(info.value?.weights.issued)-units(info.value?.outputWeight)-units(info.value?.weights.returned))throw Error('全部还料合计超过本批次可还额度')}
const returnForm=ref<FormInstance>(),quantityInputs=new WeakMap<object,string>()
const formModel=computed(()=>({checked:checked.value,date:date.value,operators:operators.value,keeper:keeper.value,reason:reason.value,lines:lines.value}))
const formRules={checked:[fieldRule(v=>v===true?'':'请先确认全部实物已核对','change')],date:[fieldRule(v=>v?'':'请选择还库日期','change')],operators:[fieldRule(v=>Array.isArray(v)&&v.length>0&&v.length<=20?'':'请选择1～20位经办人','change')],keeper:[fieldRule(v=>v?'':'请选择仓管员','change')],reason:[fieldRule(v=>mode.value==='RETURNED'?(String(v??'').trim()?String(v).length<=500?'':'还料原因最多500个字符':'请输入还料原因'):String(v??'').length<=500?'':'核对说明最多500个字符')]}
async function submit(){if(busy.value||loading.value||needsReload.value||!info.value||!canSettle.value)return;const validationTicket=epoch;if(!await returnForm.value?.validate().catch(()=>false)||validationTicket!==epoch||!visible.value||!canSettle.value)return;if(mode.value==='RETURNED')for(const row of lines.value)if(row.type==='SEMI_RETURN')row.quantity=Number(row.quantity);try{if(!checked.value)throw Error('请先确认全部实物已核对');if(mode.value==='RETURNED'&&!reason.value.trim())throw Error('请填写还料原因');if(mode.value==='RETURNED'){if(!lines.value.length||!operators.value.length||!keeper.value||!date.value)throw Error('请添加全部还料并填写日期、经办人和仓管员');validateRows(lines.value)}}catch(e:any){ElMessage.error(e.message);return}
 const id=target,ticket=epoch,valid=()=>current(ticket,id),groups=new Map<string,Row>();
 if(mode.value==='RETURNED')for(const row of lines.value){const key=row.type+':'+row.warehouseId;if(!groups.has(key))groups.set(key,{type:row.type,warehouseId:row.warehouseId,orderDate:date.value,operatorIds:[...operators.value],keeperId:keeper.value,reason:reason.value,lines:[]});groups.get(key)!.lines.push({sourceLineId:row.type==='PROCESS_RAW_RETURN'?null:row.sourceLineId,referenceId:row.referenceId,category:row.type==='SEMI_RETURN'?'SEMI':'RAW',netWeight:String(row.netWeight),quantity:row.type==='SEMI_RETURN'?row.quantity:0,grossWeight:row.grossWeight||null,impurity:row.impurity||null,organization:row.type==='PROCESS_RAW_RETURN'?info.value.customer:null})}
 const groupRows=[...groups.keys()].map(key=>lines.value.flatMap((row,index)=>row.type+':'+row.warehouseId===key?[index]:[]));
 const payload=JSON.parse(JSON.stringify({requestId,version:info.value.version,mode:mode.value,physicalChecked:true,reason:reason.value,documents:[...groups.values()]}));busy.value=true;error.value='';try{const response=await confirmBatchReturn(id,payload,valid);if(!valid())return;info.value=response.data;ElMessage.success('本批次已结算并生成报工');emit('saved')}catch(e:any){if(valid()){applyFieldErrors(returnForm.value,remapFieldErrors(e,path=>returnFieldPath(path,groupRows)));error.value=e?.message||'提交失败；未完成前请勿另建重复还料';if(/版本|刷新/.test(error.value))needsReload.value=true}}finally{busy.value=false}}
async function downloadTemplate(){if(!info.value||!importWarehouse.value)return ElMessage.warning('请先选择导入仓库');try{const data=await request({url:'/metal/warehouse-order/template',params:importType.value==='PROCESS_RAW_RETURN'?{type:importType.value,batchBound:true}:undefined,responseType:'blob'});const url=URL.createObjectURL(data as unknown as Blob);const link=document.createElement('a');link.href=url;link.download='还料模板.xlsx';link.click();URL.revokeObjectURL(url)}catch(e:any){ElMessage.error(e?.message||'模板下载失败')}}
async function importFile(event:Event){const input=event.target as HTMLInputElement,f=input.files?.[0];if(!f||loading.value||busy.value||!info.value)return;if(!importWarehouse.value){input.value='';ElMessage.warning('请选择导入仓库');return}const id=target,ticket=epoch,type=importType.value,warehouseId=importWarehouse.value;loading.value=true;try{const r=await importWarehouseLines(f,{...info.value,type,warehouseId,lines:lines.value.filter(l=>l.type===type)});if(!current(ticket,id)||type!==importType.value||warehouseId!==importWarehouse.value)return;const added=(r as any).data.map((l:Row)=>({...l,type,warehouseId,choice:type==='PROCESS_RAW_RETURN'?l.referenceId:l.sourceLineId,grossWeight:l.grossWeight??'',impurity:l.impurity??''}));validateRows([...lines.value,...added]);lines.value.push(...added);ElMessage.success('已加入还料清单，尚未提交')}catch(e:any){if(current(ticket,id))error.value=e?.message||'导入失败'}finally{if(current(ticket,id))loading.value=false;input.value=''}}
actionPermission.onChange(()=>{++epoch;target='';visible.value=false;loading.value=false;info.value=undefined;lines.value=[];reason.value='';checked.value=false})
onBeforeRouteLeave(()=>{if(busy.value)return false;close()});onBeforeRouteUpdate(()=>{if(busy.value)return false;close()});onBeforeUnmount(()=>{disposed=true;epoch++});defineExpose({open,close});
</script>
<style>
.batch-return-source-options{max-width:calc(100vw - 24px)}
.batch-return-source-options .el-select-dropdown__item{height:auto;min-height:34px;white-space:normal;overflow-wrap:anywhere;line-height:22px;padding:6px 32px 6px 12px}

.batch-return-dialog .el-dialog__body{max-height:75vh;overflow:auto}.batch-return-dialog .return-tools{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.batch-return-dialog .return-tools .el-select{width:180px}.batch-return-dialog .el-radio-group{flex-wrap:wrap}.batch-return-dialog .el-radio,.batch-return-dialog .el-checkbox{height:auto;white-space:normal;line-height:24px}.batch-return-dialog .el-radio__label,.batch-return-dialog .el-checkbox__label{white-space:normal}.batch-return-dialog .return-lines{width:100%}
@media(max-width:480px){.batch-return-dialog .el-form-item__label{width:80px!important}.batch-return-dialog .el-select,.batch-return-dialog .el-date-editor{max-width:100%}.batch-return-dialog .el-dialog__footer{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}}
</style>
